css:
.wrap {
  position: relative;
  display: inline-block;
  margin: 12px;
}

.trigger {
  padding: 8px 14px;
  border: 1px solid #a1a1aa;
  border-radius: 6px;
  background: #fff;
}

.menu {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 1;
  min-width: 160px;
  margin: 4px 0 0;
  padding: 6px 0;
  list-style: none;
  background: #fff;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
}

.menu li {
  padding: 8px 14px;
}

.card {
  margin: 12px;
  padding: 12px;
  background: #f4f4f5;
  border-radius: 6px;
}
